{
  "task": "plan_022",
  "description": "Conditional Granger causality analysis — tests whether canary->diversity causality survives after controlling for the other canary",
  "model": "Pythia-410M",
  "T": 10,
  "n_observations": 11,
  "method": "VAR-based Granger causality (statsmodels). Conditional test: x->y|z uses trivariate VAR so z lags are controlled.",
  "conditions": [
    {
      "alpha": "0.50", "seed": 42,
      "lag1_tests": [
        {"test": "ent->d1",  "uncond_p": 3.52e-07, "cond_p": 0.1351, "control": "ece",   "survives": false},
