        {"test": "ent->d3",  "uncond_p": 6.67e-06, "cond_p": 0.6569, "control": "ece",   "survives": false},
        {"test": "ece->d1",  "uncond_p": 1.09e-06, "cond_p": 0.0197, "control": "entropy", "survives": true},
        {"test": "ece->d2",  "uncond_p": 3.07e-06, "cond_p": 0.1726, "control": "entropy", "survives": false},
        {"test": "ece->d3",  "uncond_p": 3.54e-06, "cond_p": 0.3318, "control": "entropy", "survives": false},
        {"test": "ent->ece", "uncond_p": 0.0249,   "cond_p": 0.8548, "control": "d1",     "survives": false}
      ]
    },
