      "alpha": "0.75", "seed": 43,
      "lag1_tests": [
        {"test": "ent->d1",  "uncond_p": 3.52e-07, "cond_p": 0.1323, "control": "ece",   "survives": false},
        {"test": "ent->d2",  "uncond_p": 2.61e-07, "cond_p": 0.6563, "control": "ece",   "survives": false},
        {"test": "ent->d3",  "uncond_p": 6.67e-06, "cond_p": 0.3056, "control": "ece",   "survives": false},
        {"test": "ece->d1",  "uncond_p": 1.09e-06, "cond_p": 0.0003, "control": "entropy", "survives": true},
        {"test": "ece->d2",  "uncond_p": 3.07e-06, "cond_p": 0.0538, "control": "entropy", "survives": "marginal"},
        {"test": "ece->d3",  "uncond_p": 3.54e-06, "cond_p": 0.2602, "control": "entropy", "survives": false},
        {"test": "ent->ece", "uncond_p": 0.0081,   "cond_p": 0.1034, "control": "d1",     "survives": false}
      ]
    }
  ],
  "summary": {
    "lag_1": {
      "entropy_uncond_sig005": "12/12",
      "entropy_cond_ece_sig005": "1/12",
      "ece_uncond_sig005": "12/12",
      "ece_cond_ent_sig005": "5/12",
      "entropy_uncond_sig010": "12/12",
      "entropy_cond_ece_sig010": "4/12",
      "ece_uncond_sig010": "12/12",
      "ece_cond_ent_sig010": "6/12"
    },
    "lag_2": {
      "entropy_uncond_sig005": "2/12",
      "entropy_cond_ece_sig005": "3/12",
      "ece_uncond_sig005": "4/12",
      "ece_cond_ent_sig005": "7/12",
      "entropy_uncond_sig010": "4/12",
      "entropy_cond_ece_sig010": "5/12",
      "ece_uncond_sig010": "4/12",
      "ece_cond_ent_sig010": "7/12"
    },
    "interpretation": {
      "finding_1": "Both canaries show universal unconditional Granger causality on diversity (12/12, p<.05).",
      "finding_2": "Entropy's causal signal DISAPPEARS when controlling for ECE: 12/12 -> 1/12 (p<.05). Entropy's predictive power is almost entirely mediated through its correlation with ECE.",
      "finding_3": "ECE's causal signal PARTIALLY SURVIVES controlling for entropy: 12/12 -> 5/12 (p<.05). ECE carries unique predictive information beyond entropy, especially at alpha=0.75 (4/6 survive vs 1/6 at alpha=0.50).",
      "finding_4": "Alpha-dependent pattern: at high contamination (alpha=0.75), ECE becomes the dominant independent causal channel (4/6 survive). At onset (alpha=0.50), both canaries' conditional signals weaken — consistent with the signals being more correlated near threshold.",
      "finding_5": "Entropy does NOT Granger-cause ECE in most conditions (3/4 uncond non-sig). The two canaries are correlated but not causally chained.",
      "implication_for_paper": "ECE is the primary causal channel to diversity collapse. Entropy correlates with collapse but its predictive content is largely redundant with ECE. This addresses the confounding concern: the canaries capture partially distinct information, with ECE carrying the unique causal pathway."
    }
  },
  "script_path": "/root/autodl-tmp/distrib_canary_collapse/scripts/conditional_granger_analysis.py",
  "full_results_path": "/tmp/plan022_conditional_granger.json"
}

